class Solution:
    def maximumLength(self, s: str) -> int:
        n = len(s)
        max_len = -1

        # Since the length of s is small (up to 50), we can iterate through
        # all possible lengths of special substrings from longest to shortest.
        for length in range(n, 0, -1):
            # Check for each character 'a' through 'z'
            for char_code in range(ord('a'), ord('z') + 1):
                char = chr(char_code)
                target = char * length
                count = 0

                # Check how many times the substring target occurs in s
                for i in range(n - length + 1):
                    if s[i : i + length] == target:
                        count += 1

                if count >= 3:
                    return length

        return -1

